import { clipEnd, newId } from "./clipTime.ts";
import type { Asset, Clip, Project, Track } from "./types.ts";
import { voiceSpan, voiceTracks } from "./voiceMaster.ts";

/**
 * "Importar voz": a voice made elsewhere (generated by a voice tool and downloaded, or recorded
 * in another program) goes on the lesson's voice track, after the voice already there (from 0 in
 * a new lesson), one file after another. It is then the lesson's voice as a "Só voz" take is:
 * "Tela sobre a narração" plays it, and the presenter's video is placed by it.
 */

export interface VoiceImportLayout {
  tracks: Track[];
  clips: Clip[];
  placed: Clip[];
  /** Timeline second the first file starts at. */
  start: number;
  end: number;
}

/**
 * Files picked together in the order of their names, numbers counted as numbers ("parte 2"
 * before "parte 10"): a voice too long for its tool comes in parts named in sequence.
 */
export function voiceFileOrder(paths: readonly string[]): string[] {
  const name = (path: string): string => path.split(/[\\/]/).at(-1) ?? path;
  return [...paths].sort((a, b) =>
    name(a).localeCompare(name(b), "pt-BR", { numeric: true, sensitivity: "base" }),
  );
}

/** The track the voice goes on: the lesson's voice track, an empty "Voz" one, or a new "Voz". */
function voiceTrack(project: Pick<Project, "tracks" | "clips" | "assets">): {
  tracks: Track[];
  track: Track;
} {
  // A "Voz" track first: another voice track (a take's microphone) may be muted or apart.
  const voices = voiceTracks(project).filter((t) => !t.locked);
  const existing =
    voices.find((t) => t.name === "Voz") ??
    voices[0] ??
    project.tracks.find(
      (t) =>
        t.kind === "audio" &&
        t.name === "Voz" &&
        !t.locked &&
        !project.clips.some((c) => c.trackId === t.id),
    );
  if (existing) return { tracks: project.tracks, track: existing };
  const track: Track = {
    id: newId("t"),
    kind: "audio",
    name: "Voz",
    muted: false,
    hidden: false,
    locked: false,
  };
  return { tracks: [...project.tracks, track], track };
}

/** The files with sound on the voice track, in the order given; null when none has sound. */
export function layoutVoiceImport(
  project: Pick<Project, "tracks" | "clips" | "assets">,
  assets: readonly Asset[],
): VoiceImportLayout | null {
  const files = assets.filter((a) => a.hasAudio && a.kind !== "image" && a.duration > 0);
  if (!files.length) return null;
  const { tracks, track } = voiceTrack(project);
  // After the voice and after anything already on that track: never over a clip.
  const start = Math.max(
    voiceSpan(project)?.[1] ?? 0,
    ...project.clips.filter((c) => c.trackId === track.id).map(clipEnd),
  );
  const placed: Clip[] = [];
  let cursor = start;
  for (const asset of files) {
    placed.push({
      id: newId("c"),
      assetId: asset.id,
      trackId: track.id,
      start: cursor,
      in: 0,
      duration: asset.duration,
      volume: 1,
    });
    cursor += asset.duration;
  }
  return { tracks, clips: [...project.clips, ...placed], placed, start, end: cursor };
}
